#!/usr/bin/env Rscript
# run_dss_simulator.R
# ---------------------------------------------------------------------------
# DSS DML run on a single intrinsic-truth simulator seed.
#
# Reads the 6 per-sample .cov.gz files generated by Task 5 Step 1, builds
# a bsseq object at 3v3, runs DMLfit.multiFactor + DMLtest, and writes a
# per-CpG TSV to --out for the Phase 4 eval (eval_simulator_intrinsic.py).
#
# Adapted from benchmark/scripts/run_dss_replication.R (which is for the
# GSE263850 real cohort with smoothing + callDMR for DMR output). This
# variant is stripped to per-CpG DML output only -- DMRs are out of scope
# for the parallel-column claim.
#
# Usage:
#   Rscript run_dss_simulator.R \
#       --in-dir  benchmark/data/study1b_simulator/seed=2026000/bismark_cov \
#       --out     benchmark/data/study1b_simulator/seed=2026000/dss.tsv \
#       [--smoothing TRUE]
#
# Outputs:
#   <out>                   - per-CpG TSV with chr, pos, fdr, pval, diff
#   <out>.sessioninfo.txt   - R sessionInfo() for reproducibility
#   <out>.timing.tsv        - wall + CPU time for each phase
# ---------------------------------------------------------------------------

suppressPackageStartupMessages({
  library(optparse)
  library(data.table)
  library(bsseq)
  library(DSS)
})

opt_list <- list(
  make_option("--in-dir",    type = "character", help = "Directory containing the 6 .cov.gz files"),
  make_option("--out",       type = "character", help = "Output TSV path for per-CpG DML results"),
  make_option("--smoothing", type = "logical",   default = TRUE,
              help = "Smoothing flag for DMLfit.multiFactor (paper default TRUE)")
)
opt <- parse_args(OptionParser(option_list = opt_list))
if (is.null(opt$`in-dir`) || is.null(opt$out)) {
  stop("--in-dir and --out are required")
}

in_dir <- opt$`in-dir`
out_path <- opt$out
out_dir <- dirname(out_path)
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

# ---- Discover input files (deterministic) --------------------------------
files_all <- sort(list.files(in_dir, pattern = "\\.cov\\.gz$", full.names = TRUE))
if (length(files_all) != 6L) {
  stop(sprintf("expected 6 .cov.gz files in %s, found %d", in_dir, length(files_all)))
}
cat("input files (sorted):\n")
for (f in files_all) cat("  ", basename(f), "\n")

sample_ids <- c("treat_1", "treat_2", "treat_3", "ctrl_1", "ctrl_2", "ctrl_3")
group      <- factor(c("treat", "treat", "treat", "ctrl", "ctrl", "ctrl"),
                     levels = c("ctrl", "treat"))

# ---- Phase 1: build bsseq object from .cov files -------------------------
t_read_0 <- proc.time()
parse_one <- function(path, sid) {
  dt <- fread(path, sep = "\t", header = FALSE,
              col.names = c("chr", "start", "end", "beta", "count_M", "count_U"))
  dt[, sample := sid]
  dt
}
dt_list <- Map(parse_one, files_all, sample_ids)
all_sites <- unique(rbindlist(lapply(dt_list, function(d) d[, .(chr, start)])))
setkey(all_sites, chr, start)
n_sites <- nrow(all_sites)
cat(sprintf("union of CpG sites: %d\n", n_sites))

# Align each sample's coverage and methylated-count vectors to the union.
M_mat <- matrix(0L, nrow = n_sites, ncol = length(files_all))
Cov_mat <- matrix(0L, nrow = n_sites, ncol = length(files_all))
colnames(M_mat) <- sample_ids
colnames(Cov_mat) <- sample_ids
for (i in seq_along(dt_list)) {
  d <- dt_list[[i]]
  setkey(d, chr, start)
  merged <- d[all_sites, on = c("chr", "start")]
  M_mat[, i]   <- ifelse(is.na(merged$count_M), 0L, merged$count_M)
  Cov_mat[, i] <- ifelse(is.na(merged$count_M) | is.na(merged$count_U),
                         0L, merged$count_M + merged$count_U)
}

bs <- BSseq(
  chr = all_sites$chr,
  pos = all_sites$start,
  M = M_mat, Cov = Cov_mat,
  sampleNames = sample_ids
)
pData(bs)$group <- group
t_read <- proc.time() - t_read_0
cat(sprintf("bsseq: %d sites x %d samples\n", nrow(bs), ncol(bs)))

# ---- Phase 2: DMLfit.multiFactor + DMLtest -------------------------------
t_fit_0 <- proc.time()
# DSS expects `design` to be a data.frame of model variables (NOT a model
# matrix). DMLfit.multiFactor then assembles the model matrix internally
# from `formula`. The intercept is automatic; the group factor's
# treatment-level coefficient gets coef index 2.
design_df <- data.frame(group = group)
fit <- DMLfit.multiFactor(bs, design = design_df, formula = ~ group,
                          smoothing = opt$smoothing)
t_fit <- proc.time() - t_fit_0
cat(sprintf("DMLfit.multiFactor (smoothing=%s): done\n", opt$smoothing))

t_test_0 <- proc.time()
# coef = "grouptreat" -- the slope for the treatment level relative to
# control. Passing the coef name is more robust than positional index
# because DMLfit re-orders depending on factor encoding.
test <- DMLtest.multiFactor(fit, coef = "grouptreat")
t_test <- proc.time() - t_test_0
cat(sprintf("DMLtest.multiFactor: %d rows tested\n", nrow(test)))

# ---- Write per-CpG output ------------------------------------------------
# Standardise columns: chr, pos, stat, pvalue, qvalue (fdr), meth_diff.
# DMLtest returns: chr, pos, stat, pvals, fdrs (+ diff via bsseq mean).
# Compute mean methylation diff per CpG explicitly so eval has it.
# Use type="raw" because we have not run bsseq::BSmooth() on `bs`; DSS
# does its own smoothing inside DMLfit but does not write smoothed
# coverages back to the BSseq object.
raw_meth <- getMeth(bs, type = "raw")
mean_beta_treat <- rowMeans(raw_meth[, group == "treat", drop = FALSE], na.rm = TRUE)
mean_beta_ctrl  <- rowMeans(raw_meth[, group == "ctrl",  drop = FALSE], na.rm = TRUE)
meth_diff <- mean_beta_treat - mean_beta_ctrl

# Align meth_diff to the test rows (DMLtest may drop sites with insufficient coverage).
test_keys <- paste0(test$chr, ":", test$pos)
all_keys <- paste0(all_sites$chr, ":", all_sites$start)
idx <- match(test_keys, all_keys)

out_df <- data.frame(
  chr       = test$chr,
  pos       = test$pos,
  stat      = test$stat,
  pvalue    = test$pvals,
  qvalue    = test$fdrs,
  meth_diff = meth_diff[idx]
)
write.table(out_df, file = out_path, sep = "\t", quote = FALSE, row.names = FALSE)
cat(sprintf("wrote %s (%d rows)\n", out_path, nrow(out_df)))

# ---- Timings sidecar ------------------------------------------------------
timing_df <- data.frame(
  phase    = c("read+bsseq", "DMLfit.multiFactor", "DMLtest.multiFactor"),
  wall_s   = c(t_read["elapsed"], t_fit["elapsed"], t_test["elapsed"]),
  cpu_s    = c(t_read["user.self"] + t_read["sys.self"],
               t_fit["user.self"] + t_fit["sys.self"],
               t_test["user.self"] + t_test["sys.self"])
)
timing_path <- paste0(out_path, ".timing.tsv")
write.table(timing_df, file = timing_path, sep = "\t", quote = FALSE, row.names = FALSE)
cat(sprintf("wrote %s\n", timing_path))

# ---- sessionInfo ----------------------------------------------------------
sinfo_path <- paste0(out_path, ".sessioninfo.txt")
sink(sinfo_path)
cat("# run_dss_simulator.R session info\n\n")
cat(sprintf("# in_dir   : %s\n", in_dir))
cat(sprintf("# out      : %s\n", out_path))
cat(sprintf("# smoothing: %s\n\n", opt$smoothing))
print(sessionInfo())
sink()
cat(sprintf("wrote %s\n", sinfo_path))

cat("\nDONE\n")
